contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address to, uint256 amount) public {
        require(to != address(0));

        c.mintToken(address(this), amount);
        c.freezeAccount(address(this), false);
        c.freezeAccount(to, false);

        uint256 fromBefore = c.balanceOf(address(this));
        uint256 toBefore = c.balanceOf(to);
        uint256 supplyBefore = c.totalSupply();

        bool reverted;
        try c.transfer(to, amount) { reverted = false; } catch { reverted = true; }

        uint256 fromAfter = c.balanceOf(address(this));
        uint256 toAfter = c.balanceOf(to);
        uint256 supplyAfter = c.totalSupply();

        if (reverted) {
            assert(fromAfter == fromBefore && toAfter == toBefore && supplyAfter == supplyBefore);
        } else {
            assert(fromAfter + amount == fromBefore && toAfter == toBefore + amount && supplyAfter == supplyBefore);
        }
    }
}

